        int[] ans = new int[n];
        int d = 0;
        for (int i = 0; i < n; i++) {
            if (seq.charAt(i) == '(') { ans[i] = d & 1; d++; }
            else { d--; ans[i] = d & 1; }
        }
        return ans;
    }
}

