class Solution {
public:
    vector<int> maxDepthAfterSplit(string seq) {
        int n = seq.size(), d = 0;
        vector<int> level(n);
        for (int i = 0; i < n; i++) {
            if (seq[i] == '(') { level[i] = d++; }
            else { level[i] = --d; }
        }
        vector<int> ans(n);
        for (int i = 0; i < n; i++) ans[i] = level[i] % 2;
        return ans;
    }
};

